-- Seed / upsert channels from more-updates.csv (batch 3).
-- Row 174 skipped (name, not a channel ID).
-- Duplicates handled by ON CONFLICT.
-- language_manual set where Language column was populated.
-- "Australia" in Status column treated as state/country.

on conflict (youtube_channel_id) do update set
  channel_type    = excluded.channel_type,
  city            = excluded.city,
  state           = excluded.state,
  owned_by        = excluded.owned_by,
  language_manual = excluded.language_manual,
  is_active       = excluded.is_active,
  updated_at      = now();
